import{_ as r,a,b as n,c as t,d as i}from"./chunks/profile-edit.DyxMdkEa.js";import{_ as o,o as d,c as s,a3 as l}from"./chunks/framework.BlfGB29P.js";const D=JSON.parse('{"title":"3D Printer Card","description":"Kompakte Home-Assistant-Card für Klipper und Moonraker mit Profilen, Kamera und Temperaturgraphen.","frontmatter":{"title":"3D Printer Card","description":"Kompakte Home-Assistant-Card für Klipper und Moonraker mit Profilen, Kamera und Temperaturgraphen."},"headers":[],"relativePath":"projects/3d-printer-card/index.md","filePath":"projects/3d-printer-card/index.md","lastUpdated":1795870835000}'),u={name:"projects/3d-printer-card/index.md"};function c(h,e,p,m,g,f){return d(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="_3d-printer-card" tabindex="-1">3D Printer Card <a class="header-anchor" href="#_3d-printer-card" aria-label="Permalink to &quot;3D Printer Card&quot;">​</a></h1><p><a href="/en/projects/3d-printer-card/">English</a> · <a href="/fr/projects/3d-printer-card/">Français</a></p><p><strong>Version 0.1.7. Funktioniert nur mit Klipper und Moonraker.</strong> Die <a href="https://github.com/marcolivierarsenault/moonraker-home-assistant" target="_blank" rel="noreferrer">Moonraker-Integration</a> muss installiert und für jeden Drucker eingerichtet sein. Die Card verwendet deren HA-Entitäten ohne eigene Anmeldung oder zusätzliche Druckerverbindung.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=3d-printer-card&amp;category=plugin" target="_blank" rel="noreferrer"><img src="'+r+'" alt="Im Marketplace öffnen"></a></p><ol><li>Einstellungen sichern. Die <a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=marcolivierarsenault&amp;repository=moonraker-home-assistant&amp;category=integration" target="_blank" rel="noreferrer">Moonraker-Integration im Marketplace</a> installieren und konfigurieren.</li><li><code>https://github.com/rockbaer2007/3d-printer-card</code> im Marketplace als benutzerdefiniertes <strong>Dashboard</strong>-Repository hinzufügen und herunterladen. Noch nicht im allgemeinen Marketplace-Katalog gelistet.</li><li>Ressource <code>/hacsfiles/3d-printer-card/3d-printer-card.js</code> als <strong>JavaScript-Modul</strong> prüfen und Browser neu laden. Eine bisherige lokale Ressource ersetzen; nicht beide gleichzeitig laden.</li><li>Im Dashboard <strong>3D Printer Card</strong> hinzufügen. Der technische Typ bleibt <code>custom:moonraker-display-card</code>.</li></ol><p>Manuell: JS-Datei aus dem Release nach <code>/config/www/3d-printer-card/</code> kopieren und <code>/local/3d-printer-card/3d-printer-card.js?v=0.1.7</code> als JavaScript-Modul registrieren. Kein HA-Neustart nötig. Alle Entitäten der Beispielvorlage durch die eigenen ersetzen.</p><h2 id="anzeige-und-profile" tabindex="-1">Anzeige und Profile <a class="header-anchor" href="#anzeige-und-profile" aria-label="Permalink to &quot;Anzeige und Profile&quot;">​</a></h2><ul><li>Status, Dateiname, Fortschritt, Druckdauer, Restzeit, geschätzte Gesamtdauer, Fertigstellung und Schichten; außerdem Geschwindigkeit, Lüfter und Meldungen.</li><li>Düse und Bett jeweils Ist/Soll in einem Graphen; Board- und Padtemperatur jeweils Ist im zweiten Graphen. Verläufe benötigen die entsprechenden Entitäten im HA-Recorder.</li><li>Livekamera rechts mit ungefähr einem Drittel der Breite und optionaler Modellvorschau. Auf schmalen Displays untereinander.</li><li>Kompakte Wertefelder, flache Graphen, Standardbreite 24 Spalten, automatische Höhe. Eine HA-Abschnittsansicht verwenden; Panelansichten erzwingen volle Breite.</li><li>Bis zu 20 Druckerprofile mit eigenen Entitäten und Kameras.</li></ul><p>Im visuellen Editor <strong>Profil hinzufügen</strong> oder <strong>Profil bearbeiten</strong> öffnen. Über <strong>Drucker erkennen</strong> den <code>current_print_state</code>-Sensor wählen; das Entitätspräfix wird erkannt. Kameras und abweichende Zuordnungen über die native HA-Entitätensuche auswählen. <strong>Profil übernehmen</strong>, danach im äußeren Editor <strong>Speichern</strong>. Der Editor ist derzeit Deutsch; Doku DE/EN/FR. Bestehende Profile bleiben kompatibel.</p><h2 id="bilder-aus-der-praxis" tabindex="-1">Bilder aus der Praxis <a class="header-anchor" href="#bilder-aus-der-praxis" aria-label="Permalink to &quot;Bilder aus der Praxis&quot;">​</a></h2><p>Die folgenden Screenshots zeigen die Card und den deutschsprachigen Editor. Ein Klick öffnet das jeweilige Bild in voller Größe.</p><h3 id="ubersicht-mit-kamera-und-temperaturgraphen" tabindex="-1">Übersicht mit Kamera und Temperaturgraphen <a class="header-anchor" href="#ubersicht-mit-kamera-und-temperaturgraphen" aria-label="Permalink to &quot;Übersicht mit Kamera und Temperaturgraphen&quot;">​</a></h3><p><a href="/images/3d-printer-card/card-overview.png"><img src="'+a+'" alt="3D Printer Card für den Ender3 V2: Status, Fortschritt, Zeitangaben, Kamera rechts sowie Temperaturgraphen für Düse, Bett und System"></a></p><h3 id="karteneditor-mit-profilwahl-und-vorschau" tabindex="-1">Karteneditor mit Profilwahl und Vorschau <a class="header-anchor" href="#karteneditor-mit-profilwahl-und-vorschau" aria-label="Permalink to &quot;Karteneditor mit Profilwahl und Vorschau&quot;">​</a></h3><p><a href="/images/3d-printer-card/card-editor.jpeg"><img src="'+n+'" alt="Visueller Karteneditor mit Druckerprofil-Auswahl, Profil hinzufügen und Profil bearbeiten sowie der Vorschau rechts"></a></p><h3 id="druckerprofil-hinzufugen" tabindex="-1">Druckerprofil hinzufügen <a class="header-anchor" href="#druckerprofil-hinzufugen" aria-label="Permalink to &quot;Druckerprofil hinzufügen&quot;">​</a></h3><p><a href="/images/3d-printer-card/profile-add.png"><img src="'+t+'" alt="Dialog zum Hinzufügen eines Druckerprofils mit Profilname, Druckstatus-Entität, erkanntem Präfix, Kamera und Modellvorschaubild"></a></p><h3 id="druckerprofil-bearbeiten" tabindex="-1">Druckerprofil bearbeiten <a class="header-anchor" href="#druckerprofil-bearbeiten" aria-label="Permalink to &quot;Druckerprofil bearbeiten&quot;">​</a></h3><p><a href="/images/3d-printer-card/profile-edit.png"><img src="'+i+'" alt="Bearbeitung des Ender3-V2-Profils mit HA-Entitätenauswahl, Kamera, Modellvorschau und aufklappbaren Zuordnungen für Status, Temperaturen und Druckzeiten"></a></p><h2 id="druckabbruch-und-prufung" tabindex="-1">Druckabbruch und Prüfung <a class="header-anchor" href="#druckabbruch-und-prufung" aria-label="Permalink to &quot;Druckabbruch und Prüfung&quot;">​</a></h2><p>Einzige Aktion: <strong>Druck abbrechen</strong>, über den vorhandenen HA-Button bei aktivem/pausiertem Druck und betriebsbereitem Drucker. Bestätigung und erneute Zustandsprüfung sind erforderlich. Profilwechsel senden keine Druckerbefehle. Kein Filamentverbrauch und keine Gesamtstatistik.</p><p>Mit echten Entitäten unter HA 2026.11.3 geprüft: Anzeige, Kamera, Graphen und Profilbearbeitung bei erhaltenen Einstellungen. Zusätzlich 16 automatisierte Tests und Browserprüfungen mit 390, 800 und 1500 Pixeln ohne Überläufe oder ungewollte Dienstaufrufe. Kein echter laufender Druck wurde im Test abgebrochen.</p><h2 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h2><p>Kopierfertige Forenbeiträge: <a href="https://github.com/rockbaer2007/3d-printer-card/blob/main/forum/forenbeitrag-de.md" target="_blank" rel="noreferrer">Deutsch</a> · <a href="https://github.com/rockbaer2007/3d-printer-card/blob/main/forum/forum-post-en.md" target="_blank" rel="noreferrer">English</a>.</p><ul><li><a href="https://github.com/rockbaer2007/3d-printer-card" target="_blank" rel="noreferrer">GitHub und vollständige Anleitung</a></li><li><a href="https://github.com/rockbaer2007/3d-printer-card/releases/tag/v0.1.7" target="_blank" rel="noreferrer">Release 0.1.7 mit ZIP und JavaScript</a></li><li><a href="https://github.com/rockbaer2007/3d-printer-card/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">Changelog</a></li></ul><p>MIT-Lizenz. Eigenständiges Frontend-Projekt, getrennt von der Moonraker-Integration.</p>',27)])])}const P=o(u,[["render",c]]);export{D as __pageData,P as default};
